/// <summary>
/// Continuing permission notice report controller
/// Class <c>METSOContinuingPermissionNoticeController</c> controller
/// </summary>
class METSOContinuingPermissionNoticeController extends SrsReportRunController
{
}

Method.Source:
/// <summary>
/// constructor creates the instance for class
/// </summary>
/// <returns>constructor</returns>
public static METSOContinuingPermissionNoticeController construct()
{
    return new METSOContinuingPermissionNoticeController();
}

/// <summary>
/// Main method to run report
/// </summary>
/// <param name = "_args">_args</param>
static void main(Args _args)
{
    METSOContinuingPermissionNoticeController controller =
        METSOContinuingPermissionNoticeController::construct();

    PrintMgmtDocumentType type =  PrintMgmtDocumentType::METSOContinuingPermissionNote;
    PrintMgmtReportFormat printMgmtReportFormat = PrintMgmtReportFormat::findSystem(type);

    if (!printMgmtReportFormat.RecId)
    {
        select Name from printMgmtReportFormat
            where printMgmtReportFormat.DocumentType == type;
    }

    controller.parmReportName(printMgmtReportFormat.Name);
    METCommonContinuingPermissionNoticeContract contract = controller.parmReportContract().parmRdpContract() as METCommonContinuingPermissionNoticeContract;
    SalesTable salesTable = _args.record();
    contract.parmSalesId(salesTable.SalesId);

    salesLine salesLine;
    InventTable inventTable;
    METInventTable metInventTable;
    InventDim inventDim;
    METExciseRegisterEntry exciseRegister;
    METTariffItemCodeBase tariffCodeBase;

   select firstonly RecId from salesLine
        where salesLine.SalesId == salesTable.SalesId
   exists join inventTable
        where salesLine.ItemId == inventTable.ItemId
   exists join metInventTable
        where metInventTable.ItemId == inventTable.ItemId
   exists join tariffCodeBase
        where tariffCodeBase.RecId == metInventTable.METTariffItemCodeBaseRecid
        && (tariffCodeBase.CustomsExcise == METCustomExcise::C ||
             tariffCodeBase.CustomsExcise == METCustomExcise::E)
   exists join inventDim
        where inventDim.inventDimId == salesLine.InventDimId;

    if (salesLine.RecId)
    {
        controller.parmReportContract().parmRdpContract(contract);
        controller.parmArgs(_args);
        controller.parmShowDialog(false);
        controller.parmDialogCaption("@MET:METCPNotice");
        controller.startOperation();
    }
}
